"use client";

import { useCallback, useEffect, useRef, useState } from "react";
import { createPortal } from "react-dom";
import { Box, Boxes, Check, CircleAlert, Edit3, Layers3, PackagePlus, Plus, Search, Trash2, X } from "lucide-react";
import { AppShell } from "@/components/app-shell";
import { useAuth } from "@/components/auth-provider";
import { CatalogTabs } from "@/components/catalog-tabs";
import { GlobalLoader } from "@/components/global-loader";
import { Status } from "@/components/dashboard-primitives";
import { TablePagination } from "@/components/table-pagination";
import { canUser, tenantIdForUser } from "@/lib/auth-routing";
import { createBundleComponentRequest, deleteBundleComponentRequest, listBundleVariantsRequest,
  listCatalogBundlesRequest, updateBundleComponentRequest } from "@/lib/api-client";

const money = new Intl.NumberFormat("en-IN", { style: "currency", currency: "INR", maximumFractionDigits: 2 });
function Portal({ children }) { return typeof document === "undefined" ? null : createPortal(children, document.body); }
function useModal(onClose, ref, blocked) { useEffect(() => { const previous = document.body.style.overflow; document.body.style.overflow = "hidden";
  const listener = (event) => { if (event.key === "Escape" && !blocked) onClose(); }; window.addEventListener("keydown", listener);
  requestAnimationFrame(() => ref.current?.querySelector("input, button, select")?.focus()); return () => { document.body.style.overflow = previous; window.removeEventListener("keydown", listener); }; }, [blocked, onClose, ref]); }

function ComponentPicker({ accessToken, bundleId, onChange, tenantId, value }) {
  const [query, setQuery] = useState(value ? `${value.productName} · ${value.sku}` : ""); const [items, setItems] = useState([]);
  const [open, setOpen] = useState(false); const [loading, setLoading] = useState(false);
  useEffect(() => { if (!open) return undefined; let active = true; const timer = setTimeout(async () => { setLoading(true);
    try { const result = await listBundleVariantsRequest({ search: query, kind: "ALL", page: 1, pageSize: 20 }, accessToken, tenantId);
      if (active) setItems(result.items.filter((item) => item.id !== bundleId)); } catch { if (active) setItems([]); } finally { if (active) setLoading(false); } }, 180);
    return () => { active = false; clearTimeout(timer); }; }, [accessToken, bundleId, open, query, tenantId]);
  function select(item) { onChange(item); setQuery(`${item.productName} · ${item.sku}`); setOpen(false); }
  return <div className="bundle-picker"><label><span>Component SKU <em>*</em></span><div><Search aria-hidden="true" size={16} /><input autoComplete="off" placeholder="Search product name, code or SKU" required value={query} onChange={(event) => { setQuery(event.target.value); onChange(null); setOpen(true); }} onFocus={() => setOpen(true)} /></div></label>
    {open ? <div className="bundle-picker-results" role="listbox">{loading ? <span>Searching…</span> : items.length ? items.map((item) => <button aria-selected={value?.id === item.id} key={item.id} onClick={() => select(item)} role="option" type="button"><i>{item.primaryImageUrl ? <span style={{ backgroundImage: `url("${item.primaryImageUrl.replaceAll('"', '%22')}")` }} /> : <Box size={17} />}</i><span><strong>{item.productName}</strong><small>{item.variantName} · {item.sku}</small></span><span><strong>{item.salePrice === null ? "Not priced" : money.format(item.salePrice)}</strong><small>{item.availableQuantity.toLocaleString("en-IN")} available</small></span></button>) : <span>No matching active SKUs</span>}</div> : null}
    <small>{value ? `Selected ${value.sku}` : "Standard products and other bundles can be components."}</small></div>;
}

function ComponentDialog({ accessToken, bundle, item, onClose, onSaved, tenantId }) {
  const [selected, setSelected] = useState(item || null); const [form, setForm] = useState({ quantity: item?.quantity || 1,
    isOptional: item?.isOptional || false, sortOrder: item?.sortOrder ?? bundle.components.length });
  const [saving, setSaving] = useState(false); const [error, setError] = useState(""); const ref = useRef(null); useModal(onClose, ref, saving);
  async function submit(event) { event.preventDefault(); if (!item && !selected) { setError("Select a component SKU."); return; } setSaving(true); setError("");
    const input = { quantity: Number(form.quantity), isOptional: form.isOptional, sortOrder: Number(form.sortOrder) };
    try { if (item) await updateBundleComponentRequest(bundle.id, item.id, input, accessToken, tenantId);
      else await createBundleComponentRequest(bundle.id, { componentVariantId: selected.id, ...input }, accessToken, tenantId); onSaved(); }
    catch (requestError) { setError(requestError.message || "The component could not be saved."); } finally { setSaving(false); } }
  return <Portal><div className="procurement-dialog-backdrop"><form aria-labelledby="bundle-component-title" aria-modal="true" className="procurement-dialog procurement-dialog-compact bundle-component-dialog" onSubmit={submit} ref={ref} role="dialog"><header><div><p className="eyebrow">Bundle recipe · {bundle.sku}</p><h2 id="bundle-component-title">{item ? "Edit component" : "Add component SKU"}</h2><p>Set how many units are consumed when one bundle is sold.</p></div><button aria-label="Close" className="icon-button" disabled={saving} onClick={onClose} type="button"><X size={20} /></button></header><div className="procurement-dialog-body">{error ? <div className="inline-state inline-state-error" role="alert">{error}</div> : null}
    {item ? <div className="bundle-selected-component"><Box aria-hidden="true" size={18} /><span><strong>{item.productName}</strong><small>{item.variantName} · {item.sku}</small></span></div> : <ComponentPicker accessToken={accessToken} bundleId={bundle.id} onChange={setSelected} tenantId={tenantId} value={selected} />}
    <div className="form-grid bundle-component-fields"><label className="form-field"><span>Quantity <em>*</em></span><input min="0.000001" max="999999" required step="0.001" type="number" value={form.quantity} onChange={(event) => setForm((current) => ({ ...current, quantity: event.target.value }))} /><small>Units used per bundle.</small></label><label className="form-field"><span>Display order</span><input min="0" max="9999" required type="number" value={form.sortOrder} onChange={(event) => setForm((current) => ({ ...current, sortOrder: event.target.value }))} /></label><label className="switch-row catalog-span-2"><input checked={form.isOptional} onChange={(event) => setForm((current) => ({ ...current, isOptional: event.target.checked }))} type="checkbox" /><span><strong>Optional component</strong><small>Operators may omit this line when the bundle rules permit it.</small></span></label></div>
  </div><footer><span>Bundle cycles and duplicate components are blocked by the API.</span><div><button className="button button-secondary" disabled={saving} onClick={onClose} type="button">Cancel</button><button className="button button-success" disabled={saving} type="submit"><Check size={16} />{saving ? "Saving…" : item ? "Save component" : "Add component"}</button></div></footer></form></div></Portal>;
}

function RemoveDialog({ bundle, item, onClose, onConfirm, saving }) { const ref = useRef(null); useModal(onClose, ref, saving); return <Portal><div className="procurement-dialog-backdrop"><section aria-labelledby="remove-component-title" aria-modal="true" className="procurement-dialog procurement-dialog-compact" ref={ref} role="alertdialog"><header><div><p className="eyebrow">Bundle recipe</p><h2 id="remove-component-title">Remove {item.productName}?</h2><p>This SKU will no longer be consumed by {bundle.productName}.</p></div><button aria-label="Close" className="icon-button" disabled={saving} onClick={onClose} type="button"><X size={20} /></button></header><footer><span>The product and its inventory are not deleted.</span><div><button className="button button-secondary" disabled={saving} onClick={onClose} type="button">Keep component</button><button className="button button-danger" disabled={saving} onClick={onConfirm} type="button"><Trash2 size={16} />{saving ? "Removing…" : "Remove component"}</button></div></footer></section></div></Portal>; }

export default function BundlesPage() {
  const { accessToken, activeTenantId, user } = useAuth(); const tenantId = tenantIdForUser(user, "admin", activeTenantId);
  const canManage = canUser(user, "admin", "catalog.product.update", tenantId); const [filters, setFilters] = useState({ search: "", page: 1, pageSize: 10 });
  const [draftSearch, setDraftSearch] = useState(""); const [data, setData] = useState(null); const [loading, setLoading] = useState(true);
  const [error, setError] = useState(""); const [dialog, setDialog] = useState(null); const [removing, setRemoving] = useState(null); const [saving, setSaving] = useState(false);
  const load = useCallback(async () => { if (!tenantId) return; setLoading(true); setError(""); try { setData(await listCatalogBundlesRequest(filters, accessToken, tenantId)); }
    catch (requestError) { setError(requestError.message || "Bundles could not be loaded."); } finally { setLoading(false); } }, [accessToken, filters, tenantId]);
  useEffect(() => { load(); }, [load]);
  async function remove() { setSaving(true); setError(""); try { await deleteBundleComponentRequest(removing.bundle.id, removing.item.id, accessToken, tenantId); setRemoving(null); await load(); }
    catch (requestError) { setError(requestError.message || "The component could not be removed."); } finally { setSaving(false); } }
  const summary = data?.summary || { totalBundles: 0, componentLines: 0, incompleteBundles: 0 };
  return <AppShell area="admin" currentPath="/admin/catalog/bundles" eyebrow="Merchandising" title="Product bundles" description="Assemble kits from existing SKUs with controlled quantities and cycle-safe relationships.">
    <CatalogTabs currentPath="/admin/catalog/bundles" />{error ? <div className="inline-state inline-state-error" role="alert"><span>{error}</span><button onClick={() => setError("")} type="button">Dismiss</button></div> : null}
    <section className="bundle-summary" aria-label="Bundle readiness"><span><Boxes aria-hidden="true" /><small>Bundle variants</small><strong>{summary.totalBundles}</strong></span><span><Layers3 aria-hidden="true" /><small>Component lines</small><strong>{summary.componentLines}</strong></span><span data-alert={summary.incompleteBundles > 0 || undefined}><CircleAlert aria-hidden="true" /><small>Missing components</small><strong>{summary.incompleteBundles}</strong></span></section>
    <section className="bundle-workspace"><header><div><p className="eyebrow">Assembly recipes</p><h2>Bundles and kits</h2><p>Create a product with structure “Bundle / kit”, then assign its component SKUs here.</p></div><form className="bundle-search" onSubmit={(event) => { event.preventDefault(); setFilters((current) => ({ ...current, search: draftSearch.trim(), page: 1 })); }}><label className="compact-search"><Search aria-hidden="true" size={16} /><span className="sr-only">Search bundles</span><input placeholder="Bundle name, code or SKU" value={draftSearch} onChange={(event) => setDraftSearch(event.target.value)} /></label><button className="button button-secondary" type="submit">Search</button></form></header>
      {loading ? <div className="bundle-loading"><GlobalLoader inline label="Loading product bundles" /></div> : !data?.items.length ? <div className="empty-workspace bundle-empty"><PackagePlus size={30} /><h3>No bundle products found</h3><p>{filters.search ? "Change the search to find another bundle." : "Create a product and select Bundle / kit as its structure."}</p></div> : <div className="bundle-list">{data.items.map((bundle) => <article className="bundle-item" key={bundle.id}><header><div className="bundle-identity"><i>{bundle.primaryImageUrl ? <span style={{ backgroundImage: `url("${bundle.primaryImageUrl.replaceAll('"', '%22')}")` }} /> : <Boxes size={20} />}</i><span><small>{bundle.productCode}</small><strong>{bundle.productName}</strong><em>{bundle.variantName} · {bundle.sku}</em></span></div><div className="bundle-head-meta"><span><small>Selling price</small><strong>{bundle.salePrice === null ? "Not priced" : money.format(bundle.salePrice)}</strong></span><Status tone={bundle.components.length ? "positive" : "warning"}>{bundle.components.length ? `${bundle.components.length} component${bundle.components.length === 1 ? "" : "s"}` : "Setup required"}</Status>{canManage ? <button className="button button-primary" onClick={() => setDialog({ bundle })} type="button"><Plus size={16} />Add component</button> : null}</div></header>
        {bundle.components.length ? <div className="bundle-components"><div className="bundle-component-labels"><span>Component SKU</span><span>Quantity</span><span>Availability</span><span>Type</span>{canManage ? <span>Actions</span> : null}</div>{bundle.components.map((item) => <div className="bundle-component-row" key={item.id}><span className="bundle-component-name"><i>{item.primaryImageUrl ? <span style={{ backgroundImage: `url("${item.primaryImageUrl.replaceAll('"', '%22')}")` }} /> : <Box size={16} />}</i><span><strong>{item.productName}</strong><small>{item.variantName} · {item.sku}</small></span></span><span data-label="Quantity"><strong>{item.quantity.toLocaleString("en-IN")}</strong><small>per bundle</small></span><span data-label="Availability"><strong>{item.availableQuantity.toLocaleString("en-IN")}</strong><small>sellable units</small></span><span data-label="Type"><Status tone={item.isOptional ? "warning" : "neutral"}>{item.isOptional ? "Optional" : "Required"}</Status></span>{canManage ? <span className="bundle-row-actions"><button aria-label={`Edit ${item.productName}`} className="icon-button" onClick={() => setDialog({ bundle, item })} type="button"><Edit3 size={16} /></button><button aria-label={`Remove ${item.productName}`} className="icon-button" onClick={() => setRemoving({ bundle, item })} type="button"><Trash2 size={16} /></button></span> : null}</div>)}</div> : <div className="bundle-no-components"><Layers3 size={22} /><span><strong>No component SKUs assigned</strong><small>Add at least one component before submitting this bundle for approval.</small></span>{canManage ? <button className="button button-secondary" onClick={() => setDialog({ bundle })} type="button">Add first component</button> : null}</div>}
      </article>)}</div>}
      {data ? <TablePagination itemLabel="bundles" onPageChange={(page) => setFilters((current) => ({ ...current, page }))} onPageSizeChange={(pageSize) => setFilters((current) => ({ ...current, page: 1, pageSize }))} page={data.page} pageSize={data.pageSize} total={data.total} totalPages={data.totalPages} /> : null}
    </section>
    {dialog ? <ComponentDialog accessToken={accessToken} bundle={dialog.bundle} item={dialog.item} onClose={() => setDialog(null)} onSaved={async () => { setDialog(null); await load(); }} tenantId={tenantId} /> : null}
    {removing ? <RemoveDialog bundle={removing.bundle} item={removing.item} onClose={() => setRemoving(null)} onConfirm={remove} saving={saving} /> : null}
  </AppShell>;
}
